def parse_duration(s):
    import re
    match = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', s)
    if not match:
        return 0
    h, m, sec = match.groups()
    return (int(h) if h else 0) * 3600 + (int(m) if m else 0) * 60 + (int(sec) if sec else 0)

